import{_ as t,o as r,c as o,a3 as a}from"./chunks/framework.BwzYn71E.js";const c=JSON.parse('{"title":"无优先级的前馈？","description":"","frontmatter":{"translationSource":{"title":"无优先级的前馈？","archivedAt":"2026-10-31","url":"https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=BMwOTfe25aJKA3BVsZfIAh","scope":"page"},"translationLang":"zh","head":[["link",{"rel":"canonical","href":"https://kokobird28144.github.io/endfield-skydoc/zh/feedforward-without-priority"}],["link",{"rel":"alternate","hreflang":"en","href":"https://kokobird28144.github.io/endfield-skydoc/feedforward-without-priority"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://kokobird28144.github.io/endfield-skydoc/zh/feedforward-without-priority"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://kokobird28144.github.io/endfield-skydoc/feedforward-without-priority"}]]},"headers":[],"relativePath":"zh/feedforward-without-priority.md","filePath":"zh/page-BMwOTfe25aJKA3BVsZfIAh.md"}'),i={name:"zh/feedforward-without-priority.md"};function d(l,e,s,n,h,f){return r(),o("div",null,[...e[0]||(e[0]=[a('<div class="logistics-content"><span class="logistics-source-anchor" id="无优先级的前馈" aria-hidden="true"></span><h1 id="无优先级的前馈" tabindex="-1">无优先级的前馈？ <a class="header-anchor" href="#无优先级的前馈" aria-label="Permalink to &quot;无优先级的前馈？&quot;">​</a></h1><blockquote><p>源页面 ID：<code>BMwOTfe25aJKA3BVsZfIAh</code> ｜ <a href="https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=BMwOTfe25aJKA3BVsZfIAh" target="_blank" rel="noreferrer">在腾讯文档中打开</a></p></blockquote><p>在工程实现前，先考虑该结构在理论上是否成立。</p><p>在经典的逻辑中，前馈的逻辑是 输入由 广义分流器（或者取补器）分流分至抛弃支与激活支，再通过基本控制结构，使得原料充足时，抛弃支被控制结构阻塞，使得分流器将输入输出到激活支，达成原料充足→激活路更多激活物的逻辑。</p><p>在实现上通常将抛弃支使用优先汇入，汇入输入处，实现类似回仓抛弃的效果。现在考虑不使用优先级而不改变结构，那么就必须要选择该抛弃支去向。</p></div>',1)])])}const u=t(i,[["render",d]]);export{c as __pageData,u as default};
